    'location_address': locationAddress,
    'latitude': latitude,
    'longitude': longitude,
    'price_text': priceText,
    'rating': rating,
    'reviews_count': reviewsCount,
    'is_online_payment_active': isOnlinePaymentActive,
    'is_part_payment_active': isPartPaymentActive,
    'is_pay_at_location_active': isPayAtLocationActive,
    'is_cancellation_active': isCancellationActive,
    'cancellation_fee': cancellationFee,
    'cancellation_fee_percentage': cancellationFeePercentage,
    'cancellation_hours': cancellationHours,
    'is_booking_open': isBookingOpen,
    'booking_open_days': bookingOpenDays,
    'part_payment_type': partPaymentType,
    'part_payment_value': partPaymentValue,
    'contact_number': contactNumber,
