Turf sampleTurf({
  int id = 1,
  String name = 'Green Arena Turf',
  String type = 'Football / Cricket',
  String? description = 'Premium turf with floodlights',
  String? area = 'Andheri West',
  String? imageUrl = 'https://example.com/turf.jpg',
  List<String> imageUrls = const ['https://example.com/turf1.jpg'],
  String locationName = 'Mumbai Sports Complex',
