    longitude: longitude,
    priceText: priceText,
    rating: rating,
    reviewsCount: reviewsCount,
    isOnlinePaymentActive: isOnlinePaymentActive,
    isPartPaymentActive: isPartPaymentActive,
    isPayAtLocationActive: isPayAtLocationActive,
    isCancellationActive: isCancellationActive,
    cancellationFee: cancellationFee,
    cancellationFeePercentage: cancellationFeePercentage,
    cancellationHours: cancellationHours,
    isBookingOpen: isBookingOpen,
    bookingOpenDays: bookingOpenDays,
    partPaymentType: partPaymentType,
    partPaymentValue: partPaymentValue,
    contactNumber: contactNumber,
    whatsappNumber: whatsappNumber,
    sports: sports,
    facilities: facilities,
    equipments: equipments,
